import os
os.makedirs("system", exist_ok=True)

open("system/controlDict","w").write("""FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      controlDict;
}
application     snappyHexMesh;
startFrom       startTime;
startTime       0;
stopAt          endTime;
endTime         1;
deltaT          1;
writeControl    timeStep;
writeInterval   1;
purgeWrite      0;
writeFormat     ascii;
writePrecision  8;
writeCompression off;
timeFormat      general;
timePrecision   6;
runTimeModifiable true;
""")

# background box: 1.0 x 1.0 x 1.0 m, 20^3 cells -> 50 mm base cells
open("system/blockMeshDict","w").write("""FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      blockMeshDict;
}
scale 1;
vertices
(
    (-0.5 -0.5 -0.05)
    ( 0.5 -0.5 -0.05)
    ( 0.5  0.5 -0.05)
    (-0.5  0.5 -0.05)
    (-0.5 -0.5  0.95)
    ( 0.5 -0.5  0.95)
    ( 0.5  0.5  0.95)
    (-0.5  0.5  0.95)
);
blocks
(
    hex (0 1 2 3 4 5 6 7) (20 20 20) simpleGrading (1 1 1)
);
boundary
(
    background
    {
        type patch;
        faces
        (
            (0 4 7 3) (1 2 6 5) (0 1 5 4) (3 7 6 2) (0 3 2 1) (4 5 6 7)
        );
    }
);
""")

open("system/snappyHexMeshDict","w").write("""FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      snappyHexMeshDict;
}
castellatedMesh true;
snap            true;
addLayers       false;

geometry
{
    outer_cowl  { type triSurfaceMesh; file "outer_cowl.stl"; }
    core_cowl   { type triSurfaceMesh; file "core_cowl.stl"; }
    inlet       { type triSurfaceMesh; file "inlet.stl"; }
    outlet      { type triSurfaceMesh; file "outlet.stl"; }
}

castellatedMeshControls
{
    maxLocalCells       1000000;
    maxGlobalCells      3000000;
    minRefinementCells  10;
    maxLoadUnbalance    0.10;
    nCellsBetweenLevels 2;
    features
    (
        { file "outer_cowl.eMesh"; level 2; }
        { file "core_cowl.eMesh";  level 2; }
        { file "inlet.eMesh";      level 2; }
        { file "outlet.eMesh";     level 2; }
    );
    refinementSurfaces
    {
        outer_cowl  { level (2 2); }
        core_cowl   { level (2 2); }
        inlet       { level (2 2); }
        outlet      { level (2 2); }
    }
    resolveFeatureAngle 30;
    refinementRegions   {}
    locationInMesh      (0.36 0.0 0.45);
    allowFreeStandingZoneFaces true;
}

snapControls
{
    nSmoothPatch    3;
    tolerance       2.0;
    nSolveIter      100;
    nRelaxIter      5;
    nFeatureSnapIter 10;
    implicitFeatureSnap false;
    explicitFeatureSnap true;
    multiRegionFeatureSnap false;
}

addLayersControls
{
    relativeSizes true;
    layers {}
    expansionRatio 1.0;
    finalLayerThickness 0.3;
    minThickness 0.1;
    nGrow 0;
    featureAngle 60;
    nRelaxIter 3;
    nSmoothSurfaceNormals 1;
    nSmoothNormals 3;
    nSmoothThickness 10;
    maxFaceThicknessRatio 0.5;
    maxThicknessToMedialRatio 0.3;
    minMedialAxisAngle 90;
    nBufferCellsNoExtrude 0;
    nLayerIter 50;
}

meshQualityControls
{
    maxNonOrtho         65;
    maxBoundarySkewness 20;
    maxInternalSkewness 4;
    maxConcave          80;
    minVol              1e-13;
    minTetQuality       1e-15;
    minArea             -1;
    minTwist            0.02;
    minDeterminant      0.001;
    minFaceWeight       0.05;
    minVolRatio         0.01;
    minTriangleTwist    -1;
    nSmoothScale        4;
    errorReduction      0.75;
}

mergeTolerance 1e-6;
""")

open("system/surfaceFeaturesDict","w").write("""FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      surfaceFeaturesDict;
}
surfaces ("outer_cowl.stl" "core_cowl.stl" "inlet.stl" "outlet.stl");
includedAngle 150;
writeObj yes;
""")
print("dicts written:", sorted(os.listdir("system")))

import subprocess
open("system/fvSchemes","w").write("""FoamFile
{
    version     2.0;
